<?php
declare(strict_types=1);
namespace App\Services\Admin;
use App\Repositories\Admin\FebAdminRepository;use DomainException;
final class FebAdminService {
 public function __construct(private FebAdminRepository $repo){}
 public function dashboard():array{return ['workflows'=>$this->repo->workflows(),'users'=>$this->repo->users(),'chantiers'=>$this->repo->chantiers(),'accesses'=>$this->repo->accesses(),'budgets'=>$this->repo->budgets(),'history'=>$this->repo->history()];}
 public function workflow(?int $id):?array{return $id?$this->repo->workflow($id):null;}
 public function eligibleBudgets(int $chantier):array{return $chantier?$this->repo->eligibleBudgets($chantier):[];}
 public function saveWorkflow(?int $id,array $input,int $actor):int{$code=strtolower(trim((string)($input['code']??'')));$label=trim((string)($input['label']??''));$steps=$this->steps((array)($input['steps']??[]));if(!preg_match('/^[a-z0-9_-]{2,50}$/',$code)||$label===''||mb_strlen($label)>120||!$steps)throw new DomainException('Workflow ou étapes invalides.');$pdo=$this->repo->pdo();$pdo->beginTransaction();try{$before=$id?$this->repo->workflow($id,true):null;if($id&&!$before)throw new DomainException('Workflow introuvable.');if($before&&(int)$before['usage_count']>0){$old=array_map(static fn($s)=>[$s['code'],(int)$s['step_order'],$s['permission_action'],$s['assigned_user_id']],$before['steps']);$new=array_map(static fn($s)=>[$s['code'],$s['order'],$s['permission'],$s['user']],$steps);if($old!==$new)throw new DomainException('Les étapes d’un workflow déjà utilisé sont immuables.');}$q=$pdo->prepare($id?'UPDATE feb_workflows SET code=?,label=? WHERE id=?':'INSERT INTO feb_workflows(code,label) VALUES(?,?)');$q->execute($id?[$code,$label,$id]:[$code,$label]);$id=$id?:((int)$pdo->lastInsertId());if(!$before||!(int)$before['usage_count']){$pdo->prepare('DELETE FROM feb_workflow_steps WHERE workflow_id=?')->execute([$id]);$q=$pdo->prepare('INSERT INTO feb_workflow_steps(workflow_id,step_order,code,label,permission_action,assigned_user_id,active) VALUES(?,?,?,?,?,?,1)');foreach($steps as $s)$q->execute([$id,$s['order'],$s['code'],$s['label'],$s['permission'],$s['user']]);}$after=$this->repo->workflow($id);$this->repo->log($actor,'workflow',$id,$before?'modification':'creation',$before,$after);$pdo->commit();return $id;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public function toggleWorkflow(int $id,bool $active,int $actor):void{$pdo=$this->repo->pdo();$pdo->beginTransaction();try{$before=$this->repo->workflow($id,true);if(!$before)throw new DomainException('Workflow introuvable.');if(!$active){$q=$pdo->prepare("SELECT COUNT(*) FROM feb_requests WHERE workflow_id=? AND status IN ('brouillon','soumis','complement','approuve','partiellement_paye') FOR UPDATE");$q->execute([$id]);if((int)$q->fetchColumn())throw new DomainException('Ce workflow possède des FEB actives.');}$pdo->prepare('UPDATE feb_workflows SET active=? WHERE id=?')->execute([$active?1:0,$id]);$this->repo->log($actor,'workflow',$id,$active?'activation':'desactivation',$before,$this->repo->workflow($id));$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public function assignAccess(int $chantier,int $user,array $roles,int $actor):void{$valid=array_values(array_intersect(['demander','valider','payer'],$roles));$pdo=$this->repo->pdo();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT u.is_admin,MAX(CASE WHEN e.code='feb_requests' THEN p.can_view ELSE 0 END) can_view,MAX(CASE WHEN e.code='feb_requests' THEN p.can_create ELSE 0 END) can_create,MAX(CASE WHEN e.code='feb_requests' THEN p.can_update ELSE 0 END) can_update,MAX(CASE WHEN e.code='feb_requests' THEN p.can_delete ELSE 0 END) can_delete FROM users u LEFT JOIN user_permissions p ON p.user_id=u.id LEFT JOIN permission_entities e ON e.id=p.entity_id WHERE u.id=? AND u.status='active' GROUP BY u.id FOR UPDATE");$q->execute([$user]);$rights=$q->fetch();if(!$rights)throw new DomainException('Utilisateur actif introuvable.');$required=['demander'=>'can_create','valider'=>'can_update','payer'=>'can_delete'];foreach($valid as $role)if(!$rights['is_admin']&&(!$rights['can_view']||!$rights[$required[$role]]))throw new DomainException('Les permissions globales FEB ne couvrent pas le rôle '.$role.'.');$before=$this->repo->assignmentsFor($chantier,$user,true);$pdo->prepare('DELETE FROM feb_chantier_access WHERE chantier_id=? AND user_id=?')->execute([$chantier,$user]);foreach($valid as $role){$q=$pdo->prepare('INSERT INTO feb_chantier_access(chantier_id,user_id,access_role,granted_by) SELECT s.id,u.id,?,? FROM btp_chantier_starts s JOIN users u ON u.id=? WHERE s.id=?');$q->execute([$role,$actor,$user,$chantier]);if(!$q->rowCount())throw new DomainException('Chantier ou utilisateur introuvable.');}$after=$this->repo->assignmentsFor($chantier,$user);$this->repo->log($actor,'chantier_access',null,'remplacement',['chantier'=>$chantier,'user'=>$user,'roles'=>$before],['chantier'=>$chantier,'user'=>$user,'roles'=>$after]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public function assignAccessBulk(int $chantier,array $users,array $roles,int $actor):int{
  $users=array_values(array_unique(array_map('intval',$users)));
  $roles=array_values(array_unique($roles));
  if($chantier<1||!$users||count($users)>200||array_filter($users,static fn(int $id):bool=>$id<1)||!$roles||array_diff($roles,['demander','valider','payer']))throw new DomainException('Sélectionnez un chantier, des utilisateurs et des rôles valides.');
  $pdo=$this->repo->pdo();$pdo->beginTransaction();
  try{
   $check=$pdo->prepare("SELECT u.is_admin,COALESCE(MAX(p.can_view),0) can_view,COALESCE(MAX(p.can_create),0) can_create,COALESCE(MAX(p.can_update),0) can_update,COALESCE(MAX(p.can_delete),0) can_delete FROM users u LEFT JOIN permission_entities e ON e.code='feb_requests' LEFT JOIN user_permissions p ON p.user_id=u.id AND p.entity_id=e.id WHERE u.id=? AND u.status='active' GROUP BY u.id");
   $required=['demander'=>'can_create','valider'=>'can_update','payer'=>'can_delete'];
   foreach($users as $user){$check->execute([$user]);$rights=$check->fetch();if(!$rights)throw new DomainException('Utilisateur actif introuvable : #'.$user);foreach($roles as $role)if(!(int)$rights['is_admin']&&(!(int)$rights['can_view']||!(int)$rights[$required[$role]]))throw new DomainException('Permissions FEB insuffisantes pour l’utilisateur #'.$user.' ('.$role.').');}
   $exists=$pdo->prepare('SELECT id FROM btp_chantier_starts WHERE id=?');$exists->execute([$chantier]);if(!$exists->fetchColumn())throw new DomainException('Chantier introuvable.');
   $delete=$pdo->prepare('DELETE FROM feb_chantier_access WHERE chantier_id=? AND user_id=?');
   $insert=$pdo->prepare('INSERT INTO feb_chantier_access(chantier_id,user_id,access_role,granted_by) VALUES(?,?,?,?)');
   foreach($users as $user){$before=$this->repo->assignmentsFor($chantier,$user,true);$delete->execute([$chantier,$user]);foreach($roles as $role)$insert->execute([$chantier,$user,$role,$actor]);$this->repo->log($actor,'chantier_access',null,'remplacement_groupe',['chantier'=>$chantier,'user'=>$user,'roles'=>$before],['chantier'=>$chantier,'user'=>$user,'roles'=>$roles]);}
   $pdo->commit();return count($users);
  }catch(\\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
 }
 public function assignBudget(int $chantier,int $budget,int $actor):void{$pdo=$this->repo->pdo();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT cb.*,(SELECT COUNT(*) FROM feb_requests r WHERE r.chantier_id=cb.chantier_id) usage_count FROM feb_chantier_budgets cb WHERE cb.chantier_id=? FOR UPDATE');$q->execute([$chantier]);$before=$q->fetch()?:null;if($before&&(int)$before['usage_count']>0&&(int)$before['budget_id']!==$budget)throw new DomainException('Le budget d’un chantier déjà utilisé par des FEB est immuable.');$q=$pdo->prepare("SELECT b.id FROM btp_chantier_starts s JOIN btp_client_orders bc ON bc.projet_id=s.projet_id JOIN btp_prestart_budgets b ON b.order_id=bc.id AND b.status='valide' WHERE s.id=? AND b.id=? FOR UPDATE");$q->execute([$chantier,$budget]);if(!$q->fetchColumn())throw new DomainException('Ce budget validé n’appartient pas au projet du chantier.');$q=$pdo->prepare('INSERT INTO feb_chantier_budgets(chantier_id,budget_id,assigned_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE budget_id=VALUES(budget_id),assigned_by=VALUES(assigned_by),assigned_at=CURRENT_TIMESTAMP');$q->execute([$chantier,$budget,$actor]);$this->repo->log($actor,'chantier_budget',$chantier,$before?'modification':'creation',$before,['chantier_id'=>$chantier,'budget_id'=>$budget]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 private function steps(array $raw):array{$out=[];$seen=[];$activeUsers=array_column($this->repo->users(),null,'id');foreach($raw as $i=>$s){if(!is_array($s))continue;$code=strtolower(trim((string)($s['code']??'')));$label=trim((string)($s['label']??''));$permission=(string)($s['permission_action']??'update');if($code===''&&$label==='')continue;if(!preg_match('/^[a-z0-9_-]{2,50}$/',$code)||isset($seen[$code])||$label===''||!in_array($permission,['view','create','update','delete'],true))throw new DomainException('Étape '.($i+1).' invalide ou dupliquée.');$seen[$code]=true;$user=filter_var($s['assigned_user_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:null;if($user&&(!isset($activeUsers[$user])||!$this->repo->userCanFebAction($user,$permission)))throw new DomainException('Le validateur de l’étape '.($i+1).' est inactif ou ne possède pas la permission FEB requise.');$out[]=['order'=>count($out)+1,'code'=>$code,'label'=>mb_substr($label,0,120),'permission'=>$permission,'user'=>$user];}return $out;}
}
